#[cfg(any(target_os = "windows", target_os = "macos"))]
use crate::client::translate;
use hbb_common::{config, log};
#[cfg(windows)]
use tauri_winrt_notification::{Duration, Sound, Toast};

#[macro_export]
macro_rules! my_println{
    ($($arg:tt)*) => {
        #[cfg(not(windows))]
        println!("{}", format_args!($($arg)*));
        #[cfg(windows)]
        crate::platform::message_box(
            &format!("{}", format_args!($($arg)*))
        );
    };
}

/// shared by flutter and sciter main function
///
/// [Note]
/// If it returns [`None`], then the process will terminate, and flutter gui will not be started.
/// If it returns [`Some`], then the process will continue, and flutter gui will be started.
#[cfg(not(any(target_os = "android", target_os = "ios")))]
pub fn core_main() -> Option<Vec<String>> {
    if !crate::common::global_init() {
        return None;
    }
    crate::load_custom_client();
    #[cfg(windows)]
    if crate::server::mixel_receiver_input::custodian_entry() { return None; }
    #[cfg(windows)]
    if !crate::platform::windows::bootstrap() {
        // return None to terminate the process
        return None;
    }
    let mut args = Vec::new();
    let mut flutter_args = Vec::new();
    let mut i = 0;
    let mut _is_elevate = false;
    let mut _is_run_as_system = false;
    let mut _is_quick_support = false;
    let mut _mixel_attended_handoff_confirmed = false;
    let mut _is_flutter_invoke_new_connection = false;
    let mut no_server = false;
    let mut arg_exe = Default::default();
    for arg in std::env::args() {
        if i == 0 {
            arg_exe = arg;
        } else if i > 0 {
            #[cfg(feature = "flutter")]
            if [
                "--connect",
                "--play",
                "--file-transfer",
                "--view-camera",
                "--port-forward",
                "--terminal",
                "--rdp",
            ]
            .contains(&arg.as_str())
            {
                _is_flutter_invoke_new_connection = true;
            }
            if arg == "--elevate" {
                _is_elevate = true;
            } else if arg == "--run-as-system" {
                _is_run_as_system = true;
            } else if arg == "--quick_support" {
                _is_quick_support = true;
            } else if arg == "--no-server" {
                no_server = true;
            } else {
                args.push(arg);
            }
        }
        i += 1;
    }
    #[cfg(all(target_os = "macos", feature = "flutter"))]
    if args.first().map(|url| crate::server::mixel_support_url::is_reserved_support_url(url)
        && !crate::server::mixel_support_url::is_valid_support_url(url)).unwrap_or(false) {
        return None;
    }
    let _is_mixel_support_invite = args.first()
        .map(|arg| hbb_common::password_security::is_support_invite_arg(arg))
        .unwrap_or(false);
    if _is_mixel_support_invite {
        // Non-Mac/unsupported paths retain the original foreground ownership.
        #[cfg(not(all(target_os = "macos", feature = "flutter")))]
        hbb_common::password_security::hold_support_invite_attended_lease();
        #[cfg(all(target_os = "macos", feature = "flutter"))]
        if !args.first().map(|url| crate::server::mixel_support_url::is_valid_support_url(url)).unwrap_or(false)
            || args.contains(&"--noinstall".to_owned()) {
            hbb_common::password_security::hold_support_invite_attended_lease();
        }
    }
    #[cfg(any(target_os = "linux", target_os = "windows"))]
    if args.is_empty() {
        #[cfg(target_os = "linux")]
        let should_check_start_tray = crate::check_process("--server", false);
        // We can use `crate::check_process("--server", false)` on Windows.
        // Because `--server` process is the System user's process. We can't get the arguments in `check_process()`.
        // We can assume that self service running means the server is also running on Windows.
        #[cfg(target_os = "windows")]
        let should_check_start_tray = crate::platform::is_self_service_running()
            && crate::platform::is_cur_exe_the_installed();
        if should_check_start_tray && !crate::check_process("--tray", true) {
            #[cfg(target_os = "linux")]
            hbb_common::allow_err!(crate::platform::check_autostart_config());
            hbb_common::allow_err!(crate::run_me(vec!["--tray"]));
        }
    }
    #[cfg(target_os = "linux")]
    #[cfg(feature = "flutter")]
    {
        let (k, v) = ("LIBGL_ALWAYS_SOFTWARE", "1");
        if config::option2bool(
            "allow-always-software-render",
            &config::Config::get_option("allow-always-software-render"),
        ) {
            std::env::set_var(k, v);
        } else {
            std::env::remove_var(k);
        }
    }
    #[cfg(windows)]
    if args.contains(&"--connect".to_string()) || args.contains(&"--view-camera".to_string()) {
        hbb_common::platform::windows::start_cpu_performance_monitor();
    }
    #[cfg(feature = "flutter")]
    if _is_flutter_invoke_new_connection {
        return core_main_invoke_new_connection(std::env::args());
    }
    let click_setup = cfg!(windows) && args.is_empty() && crate::common::is_setup(&arg_exe);
    if click_setup && !config::is_disable_installation() {
        args.push("--install".to_owned());
        flutter_args.push("--install".to_string());
    }
    if args.contains(&"--noinstall".to_string()) {
        args.clear();
    }
    if args.len() > 0 {
        if args[0] == "--version" {
            println!("{}", crate::VERSION);
            return None;
        } else if args[0] == "--build-date" {
            println!("{}", crate::BUILD_DATE);
            return None;
        }
    }
    #[cfg(windows)]
    {
        _is_quick_support |= !crate::platform::is_installed()
            && (args.is_empty() || _is_mixel_support_invite)
            && (is_quick_support_exe(&arg_exe)
                || config::LocalConfig::get_option("pre-elevate-service") == "Y"
                || (!click_setup && crate::platform::is_elevated(None).unwrap_or(false)));
        crate::portable_service::client::set_quick_support(_is_quick_support);
        if _is_quick_support {
            hbb_common::password_security::hold_support_invite_attended_lease();
            #[cfg(feature = "flutter")]
            flutter_args.push("--mixel-attended".to_owned());
        }
        #[cfg(feature = "flutter")]
        if _is_quick_support || _is_mixel_support_invite {
            // Renew the old incoming service while this invocation still owns
            // its foreground lease. Do not release it before the asynchronous
            // WM_COPYDATA callback can acquire the existing GUI's own lease.
            if crate::ipc::set_config("mixel-support-invite-attended", "Y".to_owned()).is_err() {
                flutter_args.push("--mixel-attended-handoff-unavailable".to_owned());
            } else {
                _mixel_attended_handoff_confirmed = true;
            }
        }
    }
    let mut log_name = "".to_owned();
    if args.len() > 0 && args[0].starts_with("--") {
        let name = args[0].replace("--", "");
        if !name.is_empty() {
            log_name = name;
        }
    }
    hbb_common::init_log(false, &log_name);

    #[cfg(all(target_os = "macos", feature = "flutter"))]
    {
        let ordinary_main = args.is_empty() && !no_server && !_is_elevate && !_is_run_as_system;
        let inherited = match crate::server::mixel_gui_launch::adopt_inherited() {
            Ok(value) => value,
            Err(()) => return None,
        };
        if inherited && !ordinary_main { return None; }
        if ordinary_main {
            if !inherited && !crate::server::mixel_gui_launch::cold_route(String::new()) { return None; }
        } else if let Some(url) = args.first().filter(|url| crate::server::mixel_support_url::is_valid_support_url(url)) {
            if !crate::server::mixel_gui_launch::cold_route(url.clone()) { return None; }
        }
    }
    // linux uni (url) go here.
    #[cfg(all(target_os = "linux", feature = "flutter"))]
    if args.len() > 0 && args[0].to_ascii_lowercase().starts_with(&crate::get_uri_prefix().to_ascii_lowercase()) {
        if _is_mixel_support_invite {
            if try_send_by_dbus(args[0].clone()).is_none() { return None; }
        } else {
            return try_send_by_dbus(args[0].clone());
        }
    }

    #[cfg(windows)]
    if !crate::platform::is_installed()
        && (args.is_empty() || _is_mixel_support_invite)
        && _is_quick_support
        && !_is_elevate
        && !_is_run_as_system
        && !(_mixel_attended_handoff_confirmed && mixel_has_same_executable_main_window())
        // Cold attended support never asks for administrator credentials.
        // A stored pre-elevate-service preference still selects attended mode;
        // elevation requires the existing explicit user action instead.
        && crate::platform::is_elevated(None).unwrap_or(false)
    {
        use crate::portable_service::client;
        if let Err(e) = client::start_portable_service(client::StartPara::Direct) {
            log::error!("Failed to start portable service: {:?}", e);
        }
    }
    #[cfg(windows)]
    if !crate::platform::is_installed() && (_is_elevate || _is_run_as_system) {
        crate::platform::elevate_or_run_as_system(click_setup, _is_elevate, _is_run_as_system);
        return None;
    }
    #[cfg(all(feature = "flutter", feature = "plugin_framework"))]
    #[cfg(not(any(target_os = "android", target_os = "ios")))]
    init_plugins(&args);
    if args.is_empty() || _is_mixel_support_invite || crate::common::is_empty_uni_link(&args[0]) {
        #[cfg(feature = "flutter")]
        if _is_mixel_support_invite {
            // Forward URI/CLI handoffs on every desktop, including Linux cold
            // starts and normalized protocol case, keeping the main UI visible.
            flutter_args.extend(args.iter().cloned());
        }
        #[cfg(target_os = "macos")]
        {
            crate::platform::macos::try_remove_temp_update_dir(None);
        }

        #[cfg(windows)]
        {
            crate::platform::try_remove_temp_update_files();
            hbb_common::config::PeerConfig::preload_peers();
        }
        std::thread::spawn(move || crate::start_server(false, no_server));
    } else {
        #[cfg(windows)]
        {
            use crate::platform;
            if args[0] == "--uninstall" {
                if let Err(err) = platform::uninstall_me(true) {
                    log::error!("Failed to uninstall: {}", err);
                }
                return None;
            } else if args[0] == "--update" {
                if config::is_disable_installation() {
                    return None;
                }

                let text = match crate::platform::prepare_custom_client_update() {
                    Err(e) => {
                        log::error!("Error preparing custom client update: {}", e);
                        "Update failed!".to_string()
                    }
                    Ok(false) => "Update failed!".to_string(),
                    Ok(true) => match platform::update_me(false) {
                        Ok(_) => "Update successfully!".to_string(),
                        Err(err) => {
                            log::error!("Failed with error: {err}");
                            "Update failed!".to_string()
                        }
                    },
                };
                Toast::new(Toast::POWERSHELL_APP_ID)
                    .title(&config::APP_NAME.read().unwrap())
                    .text1(&translate(text))
                    .sound(Some(Sound::Default))
                    .duration(Duration::Short)
                    .show()
                    .ok();
                return None;
            } else if args[0] == "--after-install" {
                if let Err(err) = platform::run_after_install() {
                    log::error!("Failed to after-install: {}", err);
                }
                return None;
            } else if args[0] == "--before-uninstall" {
                if let Err(err) = platform::run_before_uninstall() {
                    log::error!("Failed to before-uninstall: {}", err);
                }
                return None;
            } else if args[0] == "--silent-install" {
                if config::is_disable_installation() {
                    return None;
                }
                #[cfg(not(windows))]
                let options = "desktopicon startmenu";
                #[cfg(windows)]
