        if !windows::native_enqueue(true, Box::new(run)) { generation.cleanup_requested.store(false, Ordering::SeqCst); }
    }
    #[cfg(target_os = "macos")] {
        if on_main_thread() { run(); } else { dispatch::Queue::main().exec_async(move || { run(); }); }
